#!/usr/bin/env node
import { Command } from 'commander';
import { buildAuditReport } from './analyzer.js';
import { fetchOpenPRs } from './github.js';
import { PRO_PURCHASE_URL, validateLicense } from './license.js';
import { applyVerdictLabel, ensureLabels, fetchPrLabels, formatClusterComment, formatWebhookText, sendWebhook, upsertStickyComment, } from './pro.js';
import * as fs from 'node:fs';
function verdictBadge(verdict) {
    switch (verdict) {
        case 'RECOMMENDED_WINNER':
            return '🏆 RECOMMENDED WINNER';
        case 'VALID_CONTENDER':
            return '✅ VALID CONTENDER';
        case 'NEEDS_SCRUTINY':
            return '⚠️ NEEDS SCRUTINY';
        case 'LIKELY_SLOP':
            return '🚨 LIKELY SLOP';
    }
}
export function formatMarkdownReport(report) {
    const lines = [];
    lines.push(`# 🛡️ PRGuard Anti-Slop & Bounty Triage Report: \`${report.repo}\``);
    lines.push(`*Scanned at: ${report.scannedAt}*`);
    lines.push('');
    lines.push('## 📊 Executive Summary');
    lines.push(`- **Total Open PRs Analyzed:** ${report.totalOpenPRs}`);
    lines.push(`- **Competing PRs in Multi-PR Issue Clusters:** ${report.competingPRCount}`);
    lines.push(`- **Flagged as Likely Bot/AI Slop:** ${report.likelySlopCount}`);
    lines.push(`- **Estimated Maintainer Review Time Saved:** ~${report.estimatedMaintainerHoursSaved} hours`);
    lines.push('');
    for (const cluster of report.clusters) {
        if (cluster.issueNumber === 'UNLINKED') {
            lines.push(`## 📂 Unlinked Pull Requests (${cluster.totalPRs})`);
        }
        else {
            lines.push(`## 🎯 Issue #${cluster.issueNumber} — ${cluster.totalPRs} Competing Pull Request(s)`);
            if (cluster.recommendedWinner) {
                lines.push(`> **🏆 Top Recommendation:** **PR #${cluster.recommendedWinner.pr.number}** by \`@${cluster.recommendedWinner.pr.user}\` (Quality Score: **${cluster.recommendedWinner.totalScore}/100**, CI: \`${cluster.recommendedWinner.pr.ciState}\`)`);
            }
        }
        lines.push('');
        lines.push('| Rank | PR | Author | Score | Verdict | CI | Diff (+ / -) | Key Signals |');
        lines.push('| :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- |');
        cluster.rankedPRs.forEach((item, idx) => {
            const sigSummary = item.signals
                .map((s) => `${s.points > 0 ? '+' : ''}${s.points} \`${s.code}\``)
                .join(', ') || 'Baseline';
            lines.push(`| #${idx + 1} | [#${item.pr.number}](${item.pr.htmlUrl}) | \`@${item.pr.user}\` | **${item.totalScore}/100** | ${verdictBadge(item.verdict)} | \`${item.pr.ciState}\` | +${item.pr.additions} / -${item.pr.deletions} (${item.pr.changedFiles}f) | ${sigSummary} |`);
        });
        lines.push('');
    }
    lines.push('---');
    lines.push('*Generated by **PRGuard** — Autonomous Anti-Slop & Bounty Triage Engine.*');
    return lines.join('\n');
}
const program = new Command();
program
    .name('prguard')
    .description('Anti-Slop PR Triage, Duplicate Cluster & Bounty Verification Engine')
    .version('1.1.0');
async function runProActions(repo, report, opts) {
    const wantsPro = Boolean(opts.comment || opts.label || opts.webhook);
    if (!wantsPro)
        return 0;
    const license = await validateLicense(opts.licenseKey ?? process.env.PRGUARD_LICENSE_KEY);
    if (!license.valid) {
        console.error(`⚠️  Pro features skipped (--comment / --label / --webhook): ${license.reason}.`);
        console.error(`   Get a PRGuard Pro license key at ${PRO_PURCHASE_URL}`);
        return 2;
    }
    console.log('🔑 PRGuard Pro license active.');
    const contested = report.clusters.filter((c) => c.issueNumber !== 'UNLINKED' && c.totalPRs > 1);
    if (opts.comment) {
        for (const cluster of contested) {
            const body = formatClusterComment(repo, cluster);
            if (opts.dryRun) {
                console.log(`[dry-run] would upsert triage comment on #${cluster.issueNumber}:\n${body}\n`);
                continue;
            }
            const action = upsertStickyComment(repo, cluster.issueNumber, body);
            console.log(`💬 Triage comment ${action} on #${cluster.issueNumber}`);
        }
    }
    if (opts.label) {
        if (!opts.dryRun)
            ensureLabels(repo);
        for (const cluster of contested) {
            for (const scored of cluster.rankedPRs) {
                if (opts.dryRun) {
                    console.log(`[dry-run] #${scored.pr.number} -> ${scored.verdict}`);
                    continue;
                }
                const current = fetchPrLabels(repo, scored.pr.number);
                const applied = applyVerdictLabel(repo, scored, current);
                if (applied)
                    console.log(`🏷️  #${scored.pr.number} labelled "${applied}"`);
            }
        }
    }
    if (opts.webhook) {
        if (opts.dryRun) {
            console.log(`[dry-run] would POST webhook summary:\n${formatWebhookText(report)}`);
        }
        else {
            await sendWebhook(opts.webhook, report);
            console.log('📣 Webhook summary sent.');
        }
    }
    return 0;
}
program
    .command('scan <repo>')
    .description('Scan open Pull Requests in a GitHub repository (owner/repo)')
    .option('-l, --limit <number>', 'Maximum open PRs to analyze', '40')
    .option('-o, --output <path>', 'Save Markdown report to file')
    .option('--json <path>', 'Save raw JSON audit data to file')
    .option('--comment', 'Pro: post/update one ranked triage comment on each contested issue')
    .option('--label', 'Pro: label PRs prguard: top-contender / needs-scrutiny / likely-slop')
    .option('--webhook <url>', 'Pro: send a summary to a Slack or Discord incoming webhook')
    .option('--license-key <key>', 'Pro license key (or set PRGUARD_LICENSE_KEY)')
    .option('--dry-run', 'Print Pro actions instead of performing them')
    .action(async (repo, opts) => {
    const limit = parseInt(opts.limit, 10) || 40;
    console.log(`🔍 Scanning up to ${limit} open PRs in ${repo}...`);
    const prs = fetchOpenPRs(repo, limit);
    const report = buildAuditReport(repo, prs);
    const md = formatMarkdownReport(report);
    if (opts.output) {
        fs.writeFileSync(opts.output, md, 'utf-8');
        console.log(`✅ Markdown report written to ${opts.output}`);
    }
    else {
        console.log('\n' + md);
    }
    if (opts.json) {
        fs.writeFileSync(opts.json, JSON.stringify(report, null, 2), 'utf-8');
        console.log(`✅ JSON report written to ${opts.json}`);
    }
    process.exitCode = await runProActions(repo, report, opts);
});
program
    .command('license <key>')
    .description('Check whether a PRGuard Pro license key is active')
    .action(async (key) => {
    const res = await validateLicense(key);
    console.log(res.valid ? `✅ ${res.reason}` : `❌ ${res.reason}`);
    process.exitCode = res.valid ? 0 : 1;
});
program.parseAsync();
